fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max = i32::MIN; // Start with the smallest possible value

    for &num in &numbers {
        if num > current_max {
            current_max = num; // Update current max if the current number is greater
        }
        result.push(current_max); // Push the current max to the result
    }

    result
}